package com.hbm.inventory;

import com.hbm.blocks.ModBlocks;
import com.hbm.blocks.machine.LaunchpadLambda;
import com.hbm.entity.missile.EntityRocketLambda;
import com.hbm.inventory.fluid.Fluids;
import com.hbm.inventory.recipes.*;
import com.hbm.inventory.recipes.loader.GenericRecipe;
import com.hbm.items.*;
import com.hbm.items.ItemEnums.EnumPartType;
import com.hbm.items.machine.ItemDrive.EnumDriveType;
import com.hbm.lib.ForgeDirection;
import com.hbm.saveddata.satellites.*;
import com.hbm.tileentity.machine.TileEntityLaunchpadLambda;
import io.netty.buffer.*;
import net.minecraft.entity.Entity;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.profiler.Profiler;
import net.minecraft.util.ResourceLocation;
import net.minecraft.util.math.BlockPos;
import net.minecraft.world.*;
import net.minecraft.world.chunk.IChunkProvider;
import net.minecraft.world.storage.*;
import net.minecraftforge.fml.common.registry.GameRegistry;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;

class LambdaLauncherTest {
    @BeforeAll static void bootstrap() throws Exception { DataConsumerRecipeTest.bootstrap();SpaceAssemblerRecipes.INSTANCE.registerDefaults();GameRegistry.registerTileEntity(Pad.class,new ResourceLocation("hbm","test_lambda_pad")); }
    @AfterEach void resetModes(){com.hbm.config.GeneralConfig.enableExpensiveMode=false;com.hbm.config.GeneralConfig.enable528=false;}
    private static ItemStack satellite(int meta){ItemStack s=new ItemStack(ModItems.satellite,1,meta);ISatChip.setFreqS(s,58680);return s;}
    private static Pad ready(TestWorld world){Pad p=new Pad();p.setWorld(world);p.setPos(new BlockPos(0,64,0));p.power=1_000_000;p.tanks[0].setFill(64_000);p.tanks[1].setFill(64_000);p.inventory.setStackInSlot(0,new ItemStack(ModItems.missile_lambda));p.inventory.setStackInSlot(1,satellite(0));return p;}
    private static NBTTagCompound control(String key){NBTTagCompound tag=new NBTTagCompound();tag.setBoolean(key,true);return tag;}
    private static GenericRecipe recipe(String key,boolean expensive,boolean mode){DataConsumerRecipeTest.defaults(expensive,mode);GenericRecipe r=AssemblyMachineRecipes.INSTANCE.recipeNameMap.get(key);assertNotNull(r);return r;}
    @Test void alcladAppendsWithoutRenumberingSixExistingParts(){assertEquals(6,EnumPartType.ALCLAD.ordinal());assertEquals(5,EnumPartType.GLASS_POLARIZED.ordinal());assertEquals(3,EnumPartType.LDE.ordinal());assertEquals(4,EnumPartType.HDE.ordinal());assertEquals(7,EnumPartType.VALUES.length);assertNotSame(ModItems.ingot_tcalloy,ModItems.ingot_tungsten_carbide);assertTrue(net.minecraftforge.oredict.OreDictionary.getOres("ingotTungstenCarbide").stream().anyMatch(stack->stack.getItem()==ModItems.ingot_tungsten_carbide));}
    @Test void launcherAcceptsRealPayloadsAndRejectsBlankOrOrbiterOnlyItems(){for(int meta=0;meta<=13;meta++){boolean expected=meta!=4;assertEquals(expected,TileEntityLaunchpadLambda.acceptsPayload(satellite(meta)),"metadata "+meta);}assertFalse(TileEntityLaunchpadLambda.acceptsPayload(new ItemStack(ModItems.sat_chip)));assertFalse(TileEntityLaunchpadLambda.acceptsPayload(new ItemStack(ModItems.sat_gerald)));assertFalse(TileEntityLaunchpadLambda.acceptsPayload(ItemStack.EMPTY));assertTrue(TileEntityLaunchpadLambda.acceptsPayload(new ItemStack(ModItems.orbital_assembly)));}
    @Test void slotFiltersKeepFluidsOutputsAndBatterySeparate(){Pad p=ready(new TestWorld(false));assertTrue(p.isItemValidForSlot(0,new ItemStack(ModItems.missile_lambda)));assertFalse(p.isItemValidForSlot(0,satellite(0)));assertTrue(p.isItemValidForSlot(1,satellite(11)));assertFalse(p.isItemValidForSlot(1,new ItemStack(ModItems.sat_chip)));assertFalse(p.isItemValidForSlot(3,new ItemStack(ModItems.missile_lambda)));assertFalse(p.isItemValidForSlot(5,new ItemStack(ModItems.missile_lambda)));assertTrue(p.isItemValidForSlot(6,new ItemStack(ModItems.battery_creative)));}
    @Test void readinessRequiresBothExactFuelThresholdsAndPower(){Pad p=ready(new TestWorld(false));assertTrue(p.canLaunch());p.tanks[0].setFill(23999);assertFalse(p.canLaunch());p.tanks[0].setFill(24000);p.tanks[1].setFill(23999);assertFalse(p.canLaunch());p.tanks[1].setFill(24000);p.power=9999;assertFalse(p.canLaunch());p.power=10000;assertTrue(p.canLaunch());}
    @Test void manualControlCannotStartUntilErectionCompletes(){Pad p=ready(new TestWorld(false));p.receiveControl(control("launch"));assertEquals(0,p.countdown);p.erected=true;int dirty=p.dirty;p.receiveControl(control("launch"));assertEquals(200,p.countdown);assertTrue(p.dirty>dirty);}
    @Test void repeatedManualControlCannotResetAnActiveCountdown(){Pad p=ready(new TestWorld(false));p.erected=true;p.countdown=77;p.receiveControl(control("launch"));assertEquals(77,p.countdown);}
    @Test void autoModeCanBeEnabledAndDisabledThroughRealControlData(){Pad p=ready(new TestWorld(false));int before=p.dirty;p.receiveControl(control("auto"));assertTrue(p.autolaunch);NBTTagCompound no=new NBTTagCompound();no.setBoolean("auto",false);p.receiveControl(no);assertFalse(p.autolaunch);assertTrue(p.dirty>before);}
    @Test void countdownCancelsIfPayloadIsRemoved(){TestWorld world=new TestWorld(false);Pad p=ready(world);p.erected=true;p.countdown=1;p.inventory.setStackInSlot(1,ItemStack.EMPTY);p.updateStates();assertEquals(0,p.countdown);assertEquals(0,world.spawns);assertEquals(64000,p.tanks[0].getFill());assertFalse(p.inventory.getStackInSlot(0).isEmpty());}
    @Test void countdownCancelsIfFuelIsDrainedBeforeLiftoff(){TestWorld world=new TestWorld(false);Pad p=ready(world);p.erected=true;p.countdown=1;p.tanks[1].setFill(23999);p.updateStates();assertEquals(0,p.countdown);assertEquals(0,world.spawns);assertEquals(64000,p.tanks[0].getFill());assertEquals(23999,p.tanks[1].getFill());}
    @Test void cancelledEntitySpawnConservesBothFuelAndPayload(){TestWorld world=new TestWorld(false);world.allowSpawn=false;Pad p=ready(world);p.erected=true;assertFalse(p.liftOff());assertEquals(1,world.spawns);assertEquals(64000,p.tanks[0].getFill());assertEquals(64000,p.tanks[1].getFill());assertFalse(p.inventory.getStackInSlot(0).isEmpty());assertFalse(p.inventory.getStackInSlot(1).isEmpty());assertTrue(p.erected);}
    @Test void successfulLiftoffConsumesExactlyOneLoadAnd24000OfEachFuel(){TestWorld world=new TestWorld(false);Pad p=ready(world);p.erected=true;assertTrue(p.liftOff());assertEquals(1,world.spawns);assertEquals(40000,p.tanks[0].getFill());assertEquals(40000,p.tanks[1].getFill());assertTrue(p.inventory.getStackInSlot(0).isEmpty());assertTrue(p.inventory.getStackInSlot(1).isEmpty());assertFalse(p.erected);EntityRocketLambda rocket=(EntityRocketLambda)world.spawned;assertEquals(58680,ISatChip.getFreqS(rocket.getSat()));assertEquals(66,rocket.posY);assertFalse(p.liftOff());assertEquals(1,world.spawns);}
    @Test void clientAndUnerectedCallsCannotBypassLiftoffGate(){Pad client=ready(new TestWorld(true));client.erected=true;assertFalse(client.liftOff());assertEquals(64000,client.tanks[0].getFill());assertFalse(ready(new TestWorld(false)).liftOff());}
    @Test void countdownCompletesOnIts200thPoweredStateUpdate(){TestWorld world=new TestWorld(false);Pad p=ready(world);p.erected=true;p.erecting=true;p.positions[1]=p.target[1]=25;p.countdown=200;for(int i=0;i<199;i++){p.updateStates();p.move();}assertEquals(0,world.spawns);assertEquals(1,p.countdown);p.updateStates();assertEquals(1,world.spawns);assertEquals(0,p.countdown);}
    @Test void fullErectionVisitsOpeningDoorsRaisedRotorAndReadyPosition(){Pad p=ready(new TestWorld(false));boolean open=false,up=false,rotated=false;int ticks=0;while(!p.erected&&ticks++<1000){p.updateStates();p.move();open|=p.doorsOpen();up|=p.erectorUp();rotated|=p.rotorDown();}assertTrue(p.erected);assertTrue(open&&up&&rotated);assertEquals(25,p.positions[1]);assertTrue(p.doorsClosed());assertTrue(p.rotorUp());}
    @Test void returningErectorClosesDoorsAndReleasesAllClamps(){Pad p=ready(new TestWorld(false));p.inventory.setStackInSlot(0,ItemStack.EMPTY);p.positions[1]=p.target[1]=25;p.erecting=false;for(int i=0;i<400;i++){p.updateStates();p.move();}assertTrue(p.erectorDown());assertTrue(p.doorsClosed());assertTrue(p.clampsUp());assertTrue(p.clampsOff());}
    @Test void movementSnapsToTargetsWithoutFloatingPointOvershoot(){Pad p=new Pad();p.positions[0]=2.99F;p.setTarget(0,3,3,60);p.move();assertEquals(3,p.positions[0]);p.positions[1]=25.001F;p.setTarget(1,25,2,60);p.move();assertEquals(25,p.positions[1]);}
    @Test void movementDelayPausesAllFivePartsTogether(){Pad p=new Pad();p.animationDelay=3;for(int i=0;i<5;i++)p.setTarget(i,1,1,10);p.move();p.move();assertArrayEquals(new float[5],p.positions);p.move();for(float v:p.positions)assertEquals(.1F,v);}
    @Test void clientInterpolatesAllFiveChannelsOverTheSameThreeTicks(){Pad source=new Pad();source.power=100;for(int i=0;i<5;i++)source.positions[i]=3*(i+1);ByteBuf buf=Unpooled.buffer();try{source.serialize(buf);Pad copy=new Pad();copy.setWorld(new TestWorld(true));copy.deserialize(buf);copy.update();for(int i=0;i<5;i++)assertEquals(i+1,copy.positions[i]);copy.update();for(int i=0;i<5;i++)assertEquals(2*(i+1),copy.positions[i]);copy.update();assertArrayEquals(source.positions,copy.positions);assertEquals(0,buf.readableBytes());}finally{buf.release();}}
    @Test void packetCarriesFuelPowerCountdownAndModeWithoutUnreadBytes(){Pad source=ready(new TestWorld(false));source.erected=true;source.erecting=true;source.autolaunch=true;source.countdown=123;ByteBuf buf=Unpooled.buffer();try{source.serialize(buf);Pad copy=new Pad();copy.deserialize(buf);assertEquals(source.power,copy.power);assertEquals(64000,copy.tanks[0].getFill());assertEquals(64000,copy.tanks[1].getFill());assertEquals(123,copy.countdown);assertTrue(copy.erected&&copy.erecting&&copy.autolaunch);assertEquals(0,buf.readableBytes());}finally{buf.release();}}
    @Test void nbtRestoresPartialAnimationCountdownAndInventory(){Pad source=ready(new TestWorld(false));source.erected=true;source.erecting=true;source.autolaunch=true;source.countdown=123;source.animationDelay=9;for(int i=0;i<5;i++){source.positions[i]=i*.25F;source.speed[i]=i*.01F;source.target[i]=i;}NBTTagCompound tag=source.writeToNBT(new NBTTagCompound());Pad copy=ready(new TestWorld(false));copy.readFromNBT(tag);assertEquals(source.power,copy.power);assertArrayEquals(source.positions,copy.positions);assertArrayEquals(source.speed,copy.speed);assertArrayEquals(source.target,copy.target);assertEquals(9,copy.animationDelay);assertEquals(123,copy.countdown);assertTrue(copy.erected&&copy.erecting&&copy.autolaunch);assertEquals(58680,ISatChip.getFreqS(copy.inventory.getStackInSlot(1)));}
    @Test void missingStateNbtKeepsOriginalTankTypesAndCapacities(){Pad p=new Pad();p.readFromNBT(new NBTTagCompound());assertSame(Fluids.GASOLINE_LEADED,p.tanks[0].getTankType());assertSame(Fluids.PEROXIDE,p.tanks[1].getTankType());assertEquals(64000,p.tanks[0].getMaxFill());assertEquals(64000,p.tanks[1].getMaxFill());assertFalse(p.erected);assertEquals(0,p.countdown);}
    @Test void allRotationsExposeFivePortsOnTheDeclaredRearRim(){LaunchpadLambda block=(LaunchpadLambda)ModBlocks.launchpad_lambda;for(ForgeDirection dir:new ForgeDirection[]{ForgeDirection.NORTH,ForgeDirection.SOUTH,ForgeDirection.WEST,ForgeDirection.EAST}){int[][] ports=block.getAllPorts(dir);assertEquals(5,ports.length);ForgeDirection rot=dir.getRotation(ForgeDirection.UP);for(int i=0;i<5;i++){assertEquals(dir.offsetX*7-rot.offsetX*(i+2),ports[i][0]);assertEquals(1,ports[i][1]);assertEquals(dir.offsetZ*7-rot.offsetZ*(i+2),ports[i][2]);assertEquals(dir.ordinal(),ports[i][3]);}}}
    @Test void rocketCopiesCallerPayloadAndPreservesExplicitOrbitInNbt(){TestRocket r=new TestRocket(new TestWorld(false));ItemStack stack=satellite(12);ISatChip.setOrbitKeyS(stack,OrbitKey.dimension(5847));r.setSat(stack);ISatChip.setFreqS(stack,1);r.motionY=1;r.onUpdate();NBTTagCompound tag=r.save();TestRocket copy=new TestRocket(new TestWorld(false));copy.load(tag);assertEquals(58680,ISatChip.getFreqS(copy.getSat()));assertEquals(12,copy.getSat().getMetadata());assertEquals(OrbitKey.dimension(5847),ISatChip.getOrbitKeyS(copy.getSat()));assertTrue(tag.getDouble("acceleration")>0);assertEquals(tag.getDouble("acceleration"),copy.save().getDouble("acceleration"));}
    @Test void rocketDeploysAtAltitudeOnlyOnServerAndOnlyOnce(){TestWorld world=new TestWorld(false);TestRocket rocket=new TestRocket(world);rocket.setSat(satellite(0));rocket.setPosition(0,601,0);rocket.onUpdate();assertTrue(rocket.isDead);assertTrue(rocket.getSat().isEmpty());assertNotNull(com.hbmspace.tileentity.TESpaceUtil.getData(world,0,0).getSatFromFreq(58680));TestRocket client=new TestRocket(new TestWorld(true));client.setSat(satellite(0));client.setPosition(0,601,0);client.onUpdate();assertFalse(client.isDead);assertFalse(client.getSat().isEmpty());}
    @Test void normalAndExpensivePadRecipesRequireOriginalFlightData(){for(boolean expensive:new boolean[]{false,true}){GenericRecipe r=recipe("ass.launchpadlambda",expensive,false);assertEquals(1200,r.duration);assertEquals(5000,r.power);assertEquals(expensive?4:5,r.inputItem.length);assertTrue(r.inputItem[r.inputItem.length-1].matchesRecipe(new ItemStack(ModItems.drive,expensive?16:1,EnumDriveType.DISK_FLIGHTDATA_PROCESSED.ordinal()),true));assertSame(ModBlocks.launchpad_lambda,((net.minecraft.item.ItemBlock)r.outputItem[0].getSingle().getItem()).getBlock());}}
    @Test void lambdaRecipeUsesAlcladAndRealCarbideWithExisting528Pool(){GenericRecipe r=recipe("ass.lambdarocket",false,true);assertEquals(1200,r.duration);assertEquals(50000,r.power);assertTrue(r.inputItem[0].matchesRecipe(new ItemStack(ModItems.part_generic,32,6),true));assertTrue(r.inputItem[1].matchesRecipe(new ItemStack(ModItems.ingot_tungsten_carbide,12),true));assertFalse(r.inputItem[1].matchesRecipe(new ItemStack(ModItems.ingot_tcalloy,12),true));assertArrayEquals(new String[]{"discover.soyuz"},r.getPools());for(String key:new String[]{"ass.alclad","ass.titaniumconstruction"})assertEquals(6,recipe(key,false,false).outputItem[0].getSingle().getMetadata());}
    @Test void carbidePyrolysisIsProducibleWithoutChangingTechnetiumSteel(){PyroOvenRecipes.recipes.clear();new PyroOvenRecipes().registerDefaults();int matches=0;for(PyroOvenRecipes.PyroOvenRecipe r:PyroOvenRecipes.recipes)if(r.outputItem!=null&&r.outputItem.getItem()==ModItems.ingot_tungsten_carbide){matches++;assertEquals(300,r.duration);assertSame(Fluids.SYNGAS,r.inputFluid.type);assertEquals(2000,r.inputFluid.fill);assertSame(Fluids.SPENTSTEAM,r.outputFluid.type);assertEquals(1000,r.outputFluid.fill);assertTrue(r.inputItem.matchesRecipe(new ItemStack(ModItems.powder_tungsten),true));}assertEquals(1,matches);}
    @Test void orphanSensorReturnsItsOriginalLinkAndFrequencyAsAnItem(){TestWorld world=new TestWorld(false);TestRocket rocket=new TestRocket(world);ItemStack sensor=satellite(12);ISatChip.setOrbitKeyS(sensor,OrbitKey.dimension(5848));rocket.setSat(sensor);rocket.setPosition(0,601,0);rocket.onUpdate();assertTrue(rocket.isDead);assertEquals(1,world.spawns);assertInstanceOf(net.minecraft.entity.item.EntityItem.class,world.spawned);ItemStack returned=((net.minecraft.entity.item.EntityItem)world.spawned).getItem();assertEquals(12,returned.getMetadata());assertEquals(58680,ISatChip.getFreqS(returned));assertEquals(OrbitKey.dimension(5848),ISatChip.getOrbitKeyS(returned));assertNotSame(sensor,returned);}
    @Test void occupiedFrequencyReturnsPayloadWithoutReplacingExistingSatellite(){TestWorld world=new TestWorld(false);Satellite existing=new SatelliteMapper();com.hbmspace.tileentity.TESpaceUtil.getData(world,0,0).putSatellite(58680,existing);TestRocket rocket=new TestRocket(world);rocket.setSat(satellite(0));rocket.setPosition(0,601,0);rocket.onUpdate();assertTrue(rocket.isDead);assertEquals(1,world.spawns);assertInstanceOf(net.minecraft.entity.item.EntityItem.class,world.spawned);assertEquals(0,((net.minecraft.entity.item.EntityItem)world.spawned).getItem().getMetadata());assertSame(existing,com.hbmspace.tileentity.TESpaceUtil.getData(world,0,0).getSatFromFreq(58680));}
    public static class Pad extends TileEntityLaunchpadLambda {int dirty;@Override public void markDirty(){dirty++;}@Override public void markChanged(){dirty++;}@Override public int getBlockMetadata(){return 12;}@Override public void networkPackNT(int range){}@Override protected void handleSound(int index,boolean running){}}
    static class TestRocket extends EntityRocketLambda {TestRocket(World world){super(world);}NBTTagCompound save(){NBTTagCompound tag=new NBTTagCompound();writeEntityToNBT(tag);return tag;}void load(NBTTagCompound tag){readEntityFromNBT(tag);}}
    static class TestWorld extends World {private final MapStorage storage=new MapStorage(null);boolean allowSpawn=true;int spawns;Entity spawned;TestWorld(boolean client){super(new SaveHandlerMP(),new WorldInfo(new NBTTagCompound()),new WorldProviderSurface(),new Profiler(),client);}@Override public boolean spawnEntity(Entity entity){spawns++;spawned=entity;return allowSpawn;}@Override public MapStorage getPerWorldStorage(){return storage;}@Override protected IChunkProvider createChunkProvider(){return null;}@Override protected boolean isChunkLoaded(int x,int z,boolean allowEmpty){return true;}}
}
